def _losing(limit):
    """Wythoff P-positions as a set, keyed with both pile orders."""
    if limit < 0:
        limit = 0
    loses = set()
    phi = (1 + 5 ** 0.5) / 2.0
    n = 0
    while True:
        xi = int(n * phi)
        yi = xi + n
        if xi > limit:
            break
        loses.add((xi, yi))
        loses.add((yi, xi))
        n += 1
    return loses


def solve(text: str) -> str:
    data = text.split()
    a = int(data[0])
    b = int(data[1])
    loses = _losing(max(a, b))

    if (a, b) in loses:
        return 'LOSE'

    for i in range(a + 1):
        for j in range(b + 1):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0 and i != j:
                continue
            if (a - i, b - j) in loses:
                return 'WIN %d %d' % (i, j)

    return 'LOSE'
